import {ReportedMap} from './DeliveryMap';
import {useRiderTracking} from './RiderTracking';
import {useEffect,useRef,useState} from 'react';
import {api} from './api';
import {AlertSettings,Blank,Feedback,Section} from './common';
import {Field,Form} from './ui';
import {money,timestamp,useResource} from './data';
export function Wallet(){
 const r=useResource(()=>api('/services/wallet')),funding=useResource(()=>api('/services/wallet/funding'));
 const [draft,setDraft]=useState(null),[checkout,setCheckout]=useState(null),[notice,setNotice]=useState(''),[checking,setChecking]=useState(false);
 const verify=async reference=>{setChecking(true);setNotice('Checking payment with Flutterwave…');try{const result=await api(`/services/wallet/funding/${encodeURIComponent(reference)}/verify`,'POST',{});setNotice(result.state==='credited'?'Payment verified. Your wallet has been credited.':'This payment has not been verified as successful yet. You can check again later.');await Promise.all([r.refresh(),funding.refresh()]);window.dispatchEvent(new Event('den:wallet-updated'));}catch(error){setNotice(error.message);}finally{setChecking(false);}};
 useEffect(()=>{const reference=new URLSearchParams(location.search).get('wallet_funding');if(reference&&/^den-wallet-[a-f0-9-]{36}$/.test(reference))void verify(reference);},[]);
 return <><h1>Your DEN wallet.</h1><p className="muted">Manage your balance and transaction history.</p><Feedback resource={r}/>{notice?<p className="notice" role="status">{notice}</p>:null}{r.data?<><section className="service-panel"><h2>Add money with Flutterwave</h2>{r.data.fundingEnabled?<><p>Fund your wallet in NGN through Flutterwave’s secure checkout. Your wallet is credited only after payment verification.</p>{checkout?<div><p>Checkout is ready for <strong>{money(checkout.amountMinor,checkout.currency)}</strong>.</p><a className="primary" href={checkout.checkoutUrl}>Open Flutterwave checkout</a><button type="button" className="text-button" onClick={()=>{setCheckout(null);setDraft(null);}}>Start another funding request</button></div>:draft?<div><h3>Review wallet funding</h3><p><strong>{money(draft.amountMinor,'NGN')}</strong></p><p className="muted">Your account email will be sent to Flutterwave for this payment. Payment methods and any applicable fees are shown at checkout. Transfers and withdrawals are not available yet.</p><Form submit="Continue to Flutterwave" onSubmit={async()=>{const result=await api('/services/wallet/funding','POST',draft);if(result.funding.state==='credited'){setNotice('This funding request is already credited.');setDraft(null);await r.refresh();}else setCheckout(result.funding);await funding.refresh();}}><button type="button" className="secondary" onClick={()=>setDraft(null)}>Cancel</button></Form></div>:<Form submit="Review funding" onSubmit={async d=>{const value=String(d.amount).trim();if(!/^\d{1,6}(\.\d{1,2})?$/.test(value))throw new Error('Enter an amount with no more than two decimal places.');const [major,minor='']=value.split('.'),amountMinor=Number(major)*100+Number(minor.padEnd(2,'0'));if(amountMinor<10000||amountMinor>10000000)throw new Error('Enter between NGN 100 and NGN 100,000.');setDraft({amountMinor,currency:'NGN',idempotencyKey:crypto.randomUUID()});}}><Field label="Amount (NGN)" name="amount" inputMode="decimal" required placeholder="100.00"/><p className="small muted">Minimum NGN 100 · Maximum NGN 100,000 per funding request.</p></Form>}</>:<p>Flutterwave funding is not connected yet. Check back after setup is complete.</p>}<div className="action-tabs wallet-live-actions"><button type="button" className="secondary" disabled>Transfer · coming next</button><button type="button" className="secondary" disabled>Withdraw · coming next</button></div></section><Section title="Wallet balances">{r.data.balances.length?<div className="wallet-grid">{r.data.balances.map(b=><div className="wallet-card" key={b.currency}><span>DEN Wallet · {b.currency}</span><strong>{money(b.amountMinor,b.currency)}</strong><small>Recorded wallet balance</small></div>)}</div>:<Blank title="No funded balance yet.">Completed, verified wallet funding will appear here.</Blank>}</Section><Section title="Funding requests" action={<button type="button" className="text-button" onClick={funding.refresh}>Refresh</button>}><Feedback resource={funding}/>{funding.data?.funding.length?<ul className="event-list">{funding.data.funding.map(f=><li key={f.reference}><strong>{money(f.amountMinor,f.currency)} · {f.state==='credited'?'Credited':'Awaiting verification'}</strong><p className="small muted">{timestamp(f.createdAt)}</p>{f.state==='pending'?<div className="wallet-live-actions">{f.checkoutUrl?<a className="secondary" href={f.checkoutUrl}>Open checkout</a>:null}<button type="button" className="secondary" disabled={checking} onClick={()=>verify(f.reference)}>{checking?'Checking…':'Check payment'}</button></div>:null}</li>)}</ul>:<p className="muted">No funding requests yet.</p>}</Section><Section title="Transaction history" action={<button type="button" className="text-button" onClick={r.refresh}>Refresh</button>}>{r.data.entries.length?<ul className="event-list">{r.data.entries.map(e=><li key={e.id}><strong>{money(e.amountMinor,e.currency)}</strong><p>{e.reference}</p><small>{timestamp(e.createdAt)}</small></li>)}</ul>:<Blank title="No transactions yet."/>}</Section><AlertSettings/></>:null}</>;
}
export function OrderServices({id,role}){
 const [panel,setPanel]=useState(''),[channel,setChannel]=useState(role==='consumer'?'rider_consumer':'manager_rider');
 return <section className="order-actions"><h3>Delivery coordination</h3><div className="action-tabs"><button className={`secondary ${panel==='tracking'?'chosen':''}`} onClick={()=>setPanel(panel==='tracking'?'':'tracking')}>OneTrack</button><button className={`secondary ${panel==='chat'?'chosen':''}`} onClick={()=>setPanel(panel==='chat'?'':'chat')}>Order chat</button></div>{panel==='tracking'?<Tracking id={id} role={role}/>:null}{panel==='chat'?<>{role==='rider'?<Field label="Conversation"><select value={channel} onChange={e=>setChannel(e.target.value)}><option value="rider_consumer">Assigned customer</option><option value="manager_rider">Organization manager</option></select></Field>:null}<OrderChat key={channel} id={id} channel={channel}/></>:null}<p className="small muted">Location and chat require an active assigned delivery. Consumers cannot privately message organizations.</p></section>;
}
function Tracking({id,role}){
 const r=useResource(()=>api(`/services/orders/${id}/tracking`),[id]),tracking=useRiderTracking();
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)void r.refresh();},15000);return()=>clearInterval(timer);},[r.refresh]);
 const sharing=tracking?.active&&tracking.orderId===id;
 return <div className="service-panel"><h3>Delivery GPS</h3><Feedback resource={r}/>{r.data&&!r.error?<><p>Status: <strong>{r.data.state==='reported'?'GPS received':r.data.state==='stale'?'Last location is out of date':r.data.state==='simulated'?'Simulated location':'Waiting for GPS'}</strong></p><ReportedMap point={r.data.point} stale={r.data.state==='stale'} simulated={r.data.state==='simulated'}/></>:null}<p className="small muted">Updates refresh every 15 seconds. ETA and traffic are not connected.</p>{role==='rider'?<><p className="small muted">Starting shares your precise GPS with this delivery’s customer. Keep DEN open and this tab visible. Sharing continues when you close this panel or change pages inside this workspace; it stops when you sign out, close DEN, stop sharing, or the assignment ends. Phone lock and background tracking are not supported.</p>{tracking?.active&&tracking.orderId!==id?<p className="notice">You are sharing GPS for another delivery. Stop sharing there before starting this order.</p>:null}<button type="button" className={sharing?'secondary':'primary'} disabled={!sharing&&(!r.data||(tracking?.active&&tracking.orderId!==id))} onClick={()=>sharing?tracking.stop():tracking.start(id)}>{sharing?'Stop sharing GPS':'Start sharing GPS'}</button>{tracking?.orderId===id?<p className="small" role="status">{tracking.message}</p>:null}</>:<p className="small muted">Your assigned rider must turn on GPS sharing. Old or missing positions are shown as unavailable rather than as a live location.</p>}<button type="button" className="text-button" onClick={r.refresh}>Refresh location</button></div>;
}

function OrderChat({id,channel}){
 const r=useResource(()=>api(`/services/orders/${id}/messages?channel=${channel}`),[id,channel]),key=useRef(crypto.randomUUID());
 return <div className="service-panel"><h3>{channel==='rider_consumer'?'Rider and customer':'Manager and rider'}</h3><Feedback resource={r}/>{r.data?<><button className="text-button" onClick={r.refresh}>Refresh conversation</button>{r.data.messages.length?<ul className="event-list">{[...r.data.messages].reverse().map(m=><li key={m.id}><p>{m.text}</p><small>{timestamp(m.createdAt)}</small></li>)}</ul>:<p className="muted">No messages yet.</p>}<Form submit="Send message" onSubmit={async d=>{await api(`/services/orders/${id}/messages?channel=${channel}`,'POST',{text:d.text,idempotencyKey:key.current});key.current=crypto.randomUUID();await r.refresh();}}><Field label="Message"><textarea name="text" required maxLength={4000}/></Field></Form></>:null}</div>;
}
